#ifndef _GL_TYPEDEF_H
#define _GL_TYPEDEF_H

/* 7.0.12 port: pull in kernel bits/types first so we can defensively
 * override BIT()/BITS() below instead of colliding with <linux/bits.h>. */
#include <linux/types.h>
#include <linux/bitops.h>

#if defined(CONFIG_HAS_EARLYSUSPEND)
#include <linux/earlysuspend.h>
#endif

/* 7.0.12 port: <linux/wakelock.h> was removed from mainline. Wake locks are
 * stubbed to no-ops (see KAL_WAKE_LOCK_* in gl_kal.h), so drop the include. */
#if CONFIG_ANDROID && defined(CFG_ENABLE_WAKE_LOCK)
#include <linux/wakelock.h>
#endif

