new_string:
#include <linux/rtnetlink.h>    /* for rtnl_lock() and rtnl_unlock() */
#include <linux/kthread.h>      /* kthread_should_stop(), kthread_run() */
/* 7.0.12 port: uaccess.h moved from <asm/uaccess.h> to <linux/uaccess.h>;
 * set_fs()/get_fs() are gone (use kernel_read()/request_firmware()). */
#include <linux/uaccess.h>      /* for copy_from_user() */
#include <linux/fs.h>           /* for firmware download */
#include <linux/vmalloc.h>

#if CFG_ENABLE_BT_OVER_WIFI
#include <linux/kfifo.h>        /* for kfifo interface (BOW only) */
#include <linux/cdev.h>         /* for cdev interface (BOW only) */
#endif

#include "hif.h"
/* 7.0.12 port: whole-chip-reset (gl_rst.h) depends on the MTK WMT/CONNSYS
 * stack that does not exist on this port; guarded out via CFG_CHIP_RESET_SUPPORT=0. */
#if CFG_CHIP_RESET_SUPPORT
    #include "gl_rst.h"
#endif

/* 7.0.12 port: MediaTek AEE (aee.h) is not available on mainline; guarded
 * out via CFG_ENABLE_AEE_MSG=0. kalSendAee* become no-ops in gl_kal.h. */
#if CFG_ENABLE_AEE_MSG
#include <linux/aee.h>
#endif

extern BOOLEAN fgIsBusAccessFailed;

