new_string:
/* 7.0.12 port: struct wake_lock removed from mainline. Wake locks are
 * stubbed to no-ops, so the handle is a plain scalar regardless of Android. */
#if CONFIG_ANDROID && defined(CFG_ENABLE_WAKE_LOCK)
typedef struct wake_lock    KAL_WAKE_LOCK_T, *P_KAL_WAKE_LOCK_T;
#else
typedef UINT_32             KAL_WAKE_LOCK_T, *P_KAL_WAKE_LOCK_T;
#endif

/* 7.0.12 STA-only port: BT-over-WiFi pulls in kfifo/cdev char-dev plumbing and
 * the AMPC net device; disabled to keep the diet STA-only. */
#define CFG_ENABLE_BT_OVER_WIFI             0

